//! Issue 2 re-check (item C1) golden-fixture harness: GPD at small `n` with the
//! ML shape near −1.
//!
//! Loads `tests/golden/gpd_smalln_negshape_golden.json` (generated by
//! `tools/generate_gpd_smalln_negshape_golden.R` from the reference R package
//! `stephenjewson/fitdistcp`) and checks the Rust GPD CP output
//! ([`fitdistcp_core::api::predict_gpd`]) on two fixed `n = 20` records whose
//! reference MLE shape is just below −1.
//!
//! # What this test proves
//!
//! Before item C1 the Rust multi-start landed at a shape just **above** −1
//! (e.g. `-0.987`), which the reference `revert2ml = (abs(v2hat) >= 1) ||
//! (v2hat > 30)` does not catch. At that shape the DMGS `1/fhat` term blows up,
//! the CP quantiles leave the support `y < -scale/shape`, and the monotone guard
//! flattens the curve far above the data (the reported `n = 20` case: `19.8` vs
//! the reference `2.06`). The fix widens the revert to `shape <= -0.98`
//! ([`fitdistcp_core::models::GPD_NEAR_MINUS_ONE_DELTA`]). This harness asserts:
//!
//! 1. **Reverted.** The Rust fit's shape is in the near-−1 band, so the CP
//!    output equals the MLE output (`cp_quantiles == ml_quantiles`).
//! 2. **Not flat far above the data.** The CP curve's maximum is at most
//!    `1.1 × max(y)` — the pre-fix curve was flat at `3.92 ×` / `1.45 ×` the
//!    data max.
//! 3. **Monotone.** The CP quantiles are non-decreasing in `p`.
//! 4. **Reference tail match.** The reference also reverts (its shape is below
//!    −1), so both curves are ML curves; the 1-in-100 CP quantile matches the
//!    reference within `GPD_SMALLN_NEGSHAPE_TAIL_RTOL`. (The low-`p` quantiles
//!    differ by up to ~30% because the fitted parameters differ — a known
//!    small-`n` MLE divergence, not a CP-formula error — so only the tail is
//!    pinned tightly.)
//!
//! # Tolerance policy
//!
//! The canonical policy lives in [`tests/golden/TOLERANCE.md`](../../tests/golden/TOLERANCE.md).
//! The tail tolerance is loose because the two fits land at different (both
//! valid) near-−1 shapes; the regression assertions (1)–(3) are exact.

use std::collections::HashMap;
use std::path::PathBuf;

use fitdistcp_core::api::{predict_gpd, PredictionRequest};
use fitdistcp_core::models::GenPareto;

/// The 1-in-100 CP quantile must match the reference within this relative
/// tolerance. Both fits revert to their ML curve; the residual is the
/// fitted-parameter difference (Rust shape ~ -0.988 vs reference ~ -1.46).
const GPD_SMALLN_NEGSHAPE_TAIL_RTOL: f64 = 5e-2;
const GPD_SMALLN_NEGSHAPE_TAIL_ATOL: f64 = 1e-6;

/// The CP curve's maximum must not exceed this multiple of the data maximum.
/// The pre-fix flat curve was `3.92 ×` (big) / `1.45 ×` (uniform) the data max.
const MAX_CP_OVER_DATA: f64 = 1.1;

fn assert_close(actual: f64, expected: f64, rtol: f64, atol: f64, what: &str) {
    let tol = atol + rtol * expected.abs();
    assert!(
        (actual - expected).abs() <= tol,
        "{what}: actual = {actual:.17e}, expected = {expected:.17e}, \
         |diff| = {:.3e} > tol = {:.3e}",
        (actual - expected).abs(),
        tol
    );
}

// --- Minimal JSON parser (test-only; avoids a serde_json dependency) --------

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Num(f64),
    Str(String),
    Arr(Vec<Json>),
    Obj(HashMap<String, Json>),
}

impl Json {
    fn as_f64(&self) -> f64 {
        match self {
            Json::Num(n) => *n,
            other => panic!("expected number, got {other:?}"),
        }
    }
    fn as_bool(&self) -> bool {
        match self {
            Json::Bool(b) => *b,
            other => panic!("expected bool, got {other:?}"),
        }
    }
    fn as_arr(&self) -> &[Json] {
        match self {
            Json::Arr(a) => a,
            other => panic!("expected array, got {other:?}"),
        }
    }
    fn as_obj(&self) -> &HashMap<String, Json> {
        match self {
            Json::Obj(o) => o,
            other => panic!("expected object, got {other:?}"),
        }
    }
    fn get(&self, key: &str) -> &Json {
        self.as_obj()
            .get(key)
            .unwrap_or_else(|| panic!("missing key {key:?}"))
    }
    fn as_f64_vec(&self) -> Vec<f64> {
        self.as_arr().iter().map(|v| v.as_f64()).collect()
    }
}

struct Parser<'a> {
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Self {
            bytes: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.bytes.len() && self.bytes[self.pos].is_ascii_whitespace() {
            self.pos += 1;
        }
    }

    fn peek(&self) -> u8 {
        self.bytes[self.pos]
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b'"' => Json::Str(self.parse_string()),
            b't' => {
                self.expect_lit("true");
                Json::Bool(true)
            }
            b'f' => {
                self.expect_lit("false");
                Json::Bool(false)
            }
            b'n' => {
                self.expect_lit("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_lit(&mut self, lit: &str) {
        assert!(
            self.bytes[self.pos..].starts_with(lit.as_bytes()),
            "expected literal {lit:?} at {}",
            self.pos
        );
        self.pos += lit.len();
    }

    fn parse_object(&mut self) -> Json {
        assert_eq!(self.peek(), b'{');
        self.pos += 1;
        let mut map = HashMap::new();
        self.skip_ws();
        if self.peek() == b'}' {
            self.pos += 1;
            return Json::Obj(map);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            assert_eq!(self.peek(), b':');
            self.pos += 1;
            let val = self.parse_value();
            map.insert(key, val);
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b'}' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in object", other as char),
            }
        }
        Json::Obj(map)
    }

    fn parse_array(&mut self) -> Json {
        assert_eq!(self.peek(), b'[');
        self.pos += 1;
        let mut items = Vec::new();
        self.skip_ws();
        if self.peek() == b']' {
            self.pos += 1;
            return Json::Arr(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_ws();
            match self.peek() {
                b',' => {
                    self.pos += 1;
                }
                b']' => {
                    self.pos += 1;
                    break;
                }
                other => panic!("unexpected byte {} in array", other as char),
            }
        }
        Json::Arr(items)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.peek(), b'"');
        self.pos += 1;
        let mut s = String::new();
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            match c {
                b'"' => {
                    self.pos += 1;
                    return s;
                }
                b'\\' => {
                    self.pos += 1;
                    let esc = self.bytes[self.pos];
                    match esc {
                        b'"' => s.push('"'),
                        b'\\' => s.push('\\'),
                        b'/' => s.push('/'),
                        b'n' => s.push('\n'),
                        b't' => s.push('\t'),
                        b'r' => s.push('\r'),
                        other => panic!("bad escape \\{}", other as char),
                    }
                    self.pos += 1;
                }
                _ => {
                    s.push(c as char);
                    self.pos += 1;
                }
            }
        }
        panic!("unterminated string");
    }

    fn parse_number(&mut self) -> Json {
        let start = self.pos;
        while self.pos < self.bytes.len() {
            let c = self.bytes[self.pos];
            if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let text = std::str::from_utf8(&self.bytes[start..self.pos]).expect("utf8 number");
        Json::Num(text.parse::<f64>().expect("valid number"))
    }
}

fn load_fixture() -> Json {
    let path: PathBuf = [
        env!("CARGO_MANIFEST_DIR"),
        "..",
        "..",
        "tests",
        "golden",
        "gpd_smalln_negshape_golden.json",
    ]
    .iter()
    .collect();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("failed to read {}: {e}", path.display()));
    Parser::new(&text).parse_value()
}

fn make_request(y: Vec<f64>, p: Vec<f64>) -> PredictionRequest {
    PredictionRequest {
        y: y.clone(),
        x: y,
        p,
        t: None,
        t0: None,
        n0: None,
        means: None,
    }
}

/// Run the item-C1 assertions for one fixture case.
fn check_case(root: &Json, model_key: &str, dataset_key: &str) {
    let models = root.get("models");
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();

    let y = datasets.get(dataset_key).as_f64_vec();
    let m = models.get(model_key);
    let ref_params = m.get("params").as_f64_vec();
    let ref_revert = m.get("revert2ml").as_bool();
    let ref_cp = m.get("cp_quantiles").as_f64_vec();

    // The reference reverts on this record (its MLE shape is below -1).
    assert!(
        ref_revert,
        "{model_key}: the reference must revert on this record (shape {} < -1)",
        ref_params[1]
    );

    let init = GenPareto.setics(&y, &[0.0, 0.0]);
    let req = make_request(y.clone(), p_grid.clone());
    let r = predict_gpd(GenPareto, &req, &init);

    // (1) Reverted: the Rust shape is in the near--1 band, so CP == ML.
    assert!(
        GenPareto.revert2ml(r.ml_params[1]),
        "{model_key}: the Rust fit shape {} must be in the near--1 revert band",
        r.ml_params[1]
    );
    assert_eq!(
        r.cp_quantiles, r.ml_quantiles,
        "{model_key}: a reverted fit must return cp_quantiles == ml_quantiles"
    );

    // (2) Not flat far above the data.
    let y_max = y.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let cp_max = r
        .cp_quantiles
        .iter()
        .cloned()
        .fold(f64::NEG_INFINITY, f64::max);
    assert!(
        cp_max <= MAX_CP_OVER_DATA * y_max,
        "{model_key}: the CP curve max {cp_max:.6} must not exceed \
         {MAX_CP_OVER_DATA} x the data max {y_max:.6} (the pre-fix flat-curve \
         regression)"
    );

    // (3) Monotone non-decreasing in p.
    for w in r.cp_quantiles.windows(2) {
        assert!(
            w[1] >= w[0] - 1e-12,
            "{model_key}: CP quantiles must be non-decreasing, got {:?}",
            r.cp_quantiles
        );
    }

    // (4) Reference tail match (both revert to ML; the tail gap is small).
    let last = r.cp_quantiles.len() - 1;
    assert_close(
        r.cp_quantiles[last],
        ref_cp[last],
        GPD_SMALLN_NEGSHAPE_TAIL_RTOL,
        GPD_SMALLN_NEGSHAPE_TAIL_ATOL,
        &format!("{model_key}.cp_quantiles[last]"),
    );

    eprintln!(
        "{model_key}: rust shape = {:.6}, cp_max = {cp_max:.6}, data_max = {y_max:.6}, \
         ref cp99 = {:.6}, rust cp99 = {:.6}",
        r.ml_params[1], ref_cp[last], r.cp_quantiles[last]
    );
}

/// The `big` record: the pre-fix Rust CP curve was flat at ~3.92 (data max 1.0).
#[test]
fn golden_gpd_smalln_negshape_big_reverts_and_is_not_flat() {
    let root = load_fixture();
    check_case(&root, "genpareto_negshape_big", "y_negshape_big");
}

/// The `uniform` record: the pre-fix Rust CP curve was flat at ~1.45 (data max
/// 1.0).
#[test]
fn golden_gpd_smalln_negshape_uniform_reverts_and_is_not_flat() {
    let root = load_fixture();
    check_case(&root, "genpareto_negshape_uniform", "y_negshape_uniform");
}

/// The pre-fix behaviour (no near-−1 revert) produced a flat curve far above the
/// data. This test pins the *symptom* by computing the raw DMGS CP on the fitted
/// parameters directly (bypassing the revert) and asserting it is flat and far
/// above the data — so a regression that removes the near-−1 guard is caught.
#[test]
fn golden_gpd_smalln_negshape_raw_dmgs_would_blow_up() {
    use fitdistcp_core::dmgs::DmgsIntegrator;

    let root = load_fixture();
    let datasets = root.get("datasets");
    let p_grid = root.get("p_grid").as_f64_vec();
    let y = datasets.get("y_negshape_big").as_f64_vec();

    let init = GenPareto.setics(&y, &[0.0, 0.0]);
    let req = make_request(y.clone(), p_grid.clone());
    let r = predict_gpd(GenPareto, &req, &init);

    // The raw DMGS CP on the fitted (near--1) params, without the revert.
    let integ = DmgsIntegrator::new(GenPareto);
    let raw = integ.cp_quantiles(&r.ml_params, &y, &p_grid);

    let y_max = y.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let raw_max = raw.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    assert!(
        raw_max > 2.0 * y_max,
        "the raw DMGS CP on the near--1 fitted params should blow up far above \
         the data (raw_max {raw_max:.6} vs data max {y_max:.6}); if it no longer \
         does, the item-C1 revert may be unnecessary"
    );

    // The reverted output is bounded (the fix).
    let cp_max = r
        .cp_quantiles
        .iter()
        .cloned()
        .fold(f64::NEG_INFINITY, f64::max);
    assert!(
        cp_max <= MAX_CP_OVER_DATA * y_max,
        "the reverted CP curve must be bounded (cp_max {cp_max:.6} vs data max {y_max:.6})"
    );
}
